-- Spawns taken from the AnoCore project's world database (AnoCore v10 repack). Credit and thanks to the AnoCore project.
-- AnoCore is a GPL-2.0 TrinityCore based server; its vanilla spawn data comes from GPL projects (CMaNGOS classic-db, TDB).
--
-- Put back creature and gameobject spawns that the AnoCore world data has and our world does not.
-- Our world comes from advocaite's TDB (vMaNGOS spawns). AnoCore's is a different spawn set, so some spots never came over.
-- Only spots with nothing of ours within 5 yards, and only up to the live-count gap per creature/object and map.
-- Safe to run twice: a row goes in only if its guid is free and no spawn of the same creature/object is within 5 yards.
-- Battlegrounds, City of Dalaran (2959), world-event spawns, herb/ore nodes, doors and traps are left out.

DROP TEMPORARY TABLE IF EXISTS `tmp_rs_c`;
CREATE TEMPORARY TABLE `tmp_rs_c` (`guid` bigint unsigned NOT NULL PRIMARY KEY,`id` int unsigned NOT NULL,`map` smallint unsigned NOT NULL,`zoneId` smallint unsigned NOT NULL,`areaId` smallint unsigned NOT NULL,`spawnDifficulties` varchar(100) NOT NULL,`equipment_id` tinyint NOT NULL,`position_x` float NOT NULL,`position_y` float NOT NULL,`position_z` float NOT NULL,`orientation` float NOT NULL,`spawntimesecs` int unsigned NOT NULL,`wander_distance` float NOT NULL,`MovementType` tinyint unsigned NOT NULL,`pool` int unsigned NOT NULL DEFAULT 0);

-- pools (one spot, one of several creatures): new pool ids 1700000+, tagged so they can be found again

-- creatures: guid free and no same creature within 5 yards; pooled ones only if their pool row is ours
SELECT t.`guid`,t.`id`,t.`map`,t.`zoneId`,t.`areaId`,t.`spawnDifficulties`,0,0,0,-1,0,t.`equipment_id`,t.`position_x`,t.`position_y`,t.`position_z`,t.`orientation`,t.`spawntimesecs`,t.`wander_distance`,0,100,t.`MovementType`,NULL,NULL,NULL,NULL,'',NULL,0
FROM `tmp_rs_c` t
WHERE EXISTS (SELECT 1 FROM `creature_template` ct WHERE ct.`entry`=t.`id`)
  AND NOT EXISTS (SELECT 1 FROM `creature` c WHERE c.`guid`=t.`guid`)
  AND NOT EXISTS (SELECT 1 FROM `creature` c WHERE c.`id`=t.`id` AND c.`map`=t.`map` AND c.`position_x` BETWEEN t.`position_x`-5 AND t.`position_x`+5 AND c.`position_y` BETWEEN t.`position_y`-5 AND t.`position_y`+5 AND POW(c.`position_x`-t.`position_x`,2)+POW(c.`position_y`-t.`position_y`,2)+POW(c.`position_z`-t.`position_z`,2)<25)
  AND (t.`pool`=0 OR EXISTS (SELECT 1 FROM `pool_template` p WHERE p.`entry`=t.`pool` AND p.`description` LIKE 'Restored AnoCore spot%'));

DROP TEMPORARY TABLE IF EXISTS `tmp_rs_pm`;
CREATE TEMPORARY TABLE `tmp_rs_pm` (`type` tinyint unsigned NOT NULL,`spawnId` bigint unsigned NOT NULL,`poolSpawnId` int unsigned NOT NULL,`chance` float NOT NULL,`id` int unsigned NOT NULL DEFAULT 0,PRIMARY KEY (`type`,`spawnId`));
SELECT m.`type`,m.`spawnId`,m.`poolSpawnId`,m.`chance`,'Restored AnoCore spot' FROM `tmp_rs_pm` m
JOIN `pool_template` p ON p.`entry`=m.`poolSpawnId` AND p.`description` LIKE 'Restored AnoCore spot%'
WHERE (m.`type`=0 AND EXISTS (SELECT 1 FROM `creature` c WHERE c.`guid`=m.`spawnId` AND c.`id`=m.`id`))
   OR (m.`type`=2 AND EXISTS (SELECT 1 FROM `pool_template` q WHERE q.`entry`=m.`spawnId` AND q.`description` LIKE 'Restored AnoCore spot%'));
-- tidy up: a restored pool whose spawns were all skipped is removed again (with its link to a parent pool)
DELETE m FROM `pool_members` m JOIN `pool_template` p ON p.`entry`=m.`spawnId` WHERE m.`type`=2 AND m.`description`='Restored AnoCore spot' AND p.`description` LIKE 'Restored AnoCore spot%' AND NOT EXISTS (SELECT 1 FROM `tmp_rs_pm` x WHERE x.`type`=0 AND x.`poolSpawnId`=p.`entry` AND EXISTS (SELECT 1 FROM `creature` c WHERE c.`guid`=x.`spawnId` AND c.`id`=x.`id`));
DELETE p FROM `pool_template` p WHERE p.`description` LIKE 'Restored AnoCore spot%' AND NOT EXISTS (SELECT 1 FROM `pool_members` m WHERE m.`poolSpawnId`=p.`entry`);
DROP TEMPORARY TABLE `tmp_rs_pm`;
DROP TEMPORARY TABLE `tmp_rs_c`;

-- gameobjects
DROP TEMPORARY TABLE IF EXISTS `tmp_rs_g`;
CREATE TEMPORARY TABLE `tmp_rs_g` (`guid` bigint unsigned NOT NULL PRIMARY KEY,`id` int unsigned NOT NULL,`map` smallint unsigned NOT NULL,`zoneId` smallint unsigned NOT NULL,`areaId` smallint unsigned NOT NULL,`spawnDifficulties` varchar(100) NOT NULL,`position_x` float NOT NULL,`position_y` float NOT NULL,`position_z` float NOT NULL,`orientation` float NOT NULL,`rotation0` float NOT NULL,`rotation1` float NOT NULL,`rotation2` float NOT NULL,`rotation3` float NOT NULL,`spawntimesecs` int NOT NULL,`animprogress` tinyint unsigned NOT NULL,`state` tinyint unsigned NOT NULL);
SELECT t.`guid`,t.`id`,t.`map`,t.`zoneId`,t.`areaId`,t.`spawnDifficulties`,0,0,0,-1,t.`position_x`,t.`position_y`,t.`position_z`,t.`orientation`,t.`rotation0`,t.`rotation1`,t.`rotation2`,t.`rotation3`,t.`spawntimesecs`,t.`animprogress`,t.`state`,'',NULL,0
FROM `tmp_rs_g` t
WHERE EXISTS (SELECT 1 FROM `gameobject_template` gt WHERE gt.`entry`=t.`id`)
  AND NOT EXISTS (SELECT 1 FROM `gameobject` g WHERE g.`guid`=t.`guid`)
  AND NOT EXISTS (SELECT 1 FROM `gameobject` g WHERE g.`id`=t.`id` AND g.`map`=t.`map` AND g.`position_x` BETWEEN t.`position_x`-5 AND t.`position_x`+5 AND g.`position_y` BETWEEN t.`position_y`-5 AND t.`position_y`+5 AND POW(g.`position_x`-t.`position_x`,2)+POW(g.`position_y`-t.`position_y`,2)+POW(g.`position_z`-t.`position_z`,2)<25);
DROP TEMPORARY TABLE `tmp_rs_g`;
